import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import { router } from 'kea-router'

import { teamLogic } from 'scenes/teamLogic'
import { urls } from 'scenes/urls'

import { insightsList } from 'products/product_analytics/frontend/generated/api'

import type { PaginatedInsightListApi } from '../../product_analytics/frontend/generated/api.schemas'
import { captureBIWorksheetAction } from './biEditorAnalytics'
import { DEFAULT_BI_CONFIG } from './biEditorTypes'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biWorksheetsLogicValues {
    currentTeamId: number | null // teamLogic
    error: string | null
    page: number
    recent: boolean
    search: string
    worksheets: Awaited<ReturnType<typeof insightsList>> | null
    worksheetsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biWorksheetsLogicActions {
    loadWorksheets: (_: void) => void
    loadWorksheetsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadWorksheetsSuccess: (
        worksheets: PaginatedInsightListApi,
        payload?: void
    ) => {
        worksheets: PaginatedInsightListApi
        payload?: void
    }
    setPage: (page: number) => {
        page: number
    }
    setRecent: (recent: boolean) => {
        recent: boolean
    }
    setSearch: (search: string) => {
        search: string
    }
}

export type biWorksheetsLogicType = MakeLogicType<biWorksheetsLogicValues, biWorksheetsLogicActions>

export const biWorksheetsLogic = kea<biWorksheetsLogicType>([
    path(['products', 'business_intelligence', 'biWorksheetsLogic']),
    connect({ values: [teamLogic, ['currentTeamId']] }),
    actions({
        setSearch: (search: string) => ({ search }),
        setPage: (page: number) => ({ page }),
        setRecent: (recent: boolean) => ({ recent }),
    }),
    reducers({
        search: ['', { setSearch: (_, { search }) => search }],
        page: [1, { setPage: (_, { page }) => page, setSearch: () => 1, setRecent: () => 1 }],
        recent: [false, { setRecent: (_, { recent }) => recent }],
        error: [null as string | null, { loadWorksheets: () => null, loadWorksheetsFailure: (_, { error }) => error }],
    }),
    loaders(({ values }) => ({
        worksheets: [
            null as Awaited<ReturnType<typeof insightsList>> | null,
            {
                loadWorksheets: async (_: void, breakpoint) => {
                    await breakpoint(250)
                    const response = await insightsList(String(values.currentTeamId), {
                        insight: 'BI',
                        basic: true,
                        saved: true,
                        limit: 50,
                        offset: (values.page - 1) * 50,
                        search: values.search.trim() || undefined,
                        ...(values.recent ? { order: '-last_viewed_at', last_viewed_date_from: '-30d' } : {}),
                    })
                    breakpoint()
                    return response
                },
            },
        ],
    })),
    listeners(({ actions }) => ({
        setSearch: () => actions.loadWorksheets(),
        setPage: () => actions.loadWorksheets(),
        setRecent: () => actions.loadWorksheets(),
    })),
    afterMount(({ actions }) => {
        const { searchParams, hashParams } = router.values
        if (searchParams.open_insight || searchParams.open_view || 'q' in hashParams || hashParams.bi) {
            router.actions.replace(
                searchParams.open_insight
                    ? urls.businessIntelligenceWorksheet(searchParams.open_insight)
                    : urls.businessIntelligenceNew(),
                searchParams,
                hashParams
            )
            return
        }
        captureBIWorksheetAction('opened', DEFAULT_BI_CONFIG)
        actions.loadWorksheets()
    }),
])
